initial_files.tools/preflight.py:
"""Release preflight: check a config tree against a signed-off manifest.

Usage: python3 tools/preflight.py <manifest.json> [config-root]

The manifest maps workspace-relative config paths to the values change
management signed off for the release. Prints PREFLIGHT OK when every
rule holds, otherwise PREFLIGHT FAIL plus one line per problem.
"""
import json
import os
import sys


def load_manifest(path):
    with open(path, encoding="utf-8") as handle:
        return json.load(handle)


def check_file(root, relative, rules):
    problems = []
    path = os.path.join(root, relative)
    try:
        with open(path, encoding="utf-8") as handle:
            text = handle.read()
    except OSError:
        return ["%s: cannot be read" % relative]
    for needle in rules.get("must_contain", []):
        if needle not in text:
            problems.append("%s: missing %r" % (relative, needle))
    for needle in rules.get("must_keep", []):
        if needle not in text:
            problems.append("%s: lost %r" % (relative, needle))
    return problems


def main(argv):
    if len(argv) < 2:
        print("usage: preflight.py <manifest.json> [config-root]")
        return 2
    root = argv[2] if len(argv) > 2 else "."
    problems = []
    for relative, rules in sorted(load_manifest(argv[1]).items()):
        problems.extend(check_file(root, relative, rules))
    if problems:
        print("PREFLIGHT FAIL")
        for problem in problems:
            print(problem)
        return 1
    print("PREFLIGHT OK")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

