initial_files.valves/stage_calib.py:
"""Stage calibration math for the tide-gate valve controllers."""

STAGE_MIN_METERS = -1.5
STAGE_MAX_METERS = 9.2
GLITCH_WINDOW_MS = 250


def clamp_to_band(value):
    if value < STAGE_MIN_METERS:
        return STAGE_MIN_METERS
    if value > STAGE_MAX_METERS:
        return STAGE_MAX_METERS
    return value


def normalize_stage_reading(raw):
    """Scale a raw stage sample into meters."""
    scaled = raw * 0.01
    return clamp_to_band(round(scaled, 3))

