initial_files.platform/sessions/vault.py:
"""Vault session locking for cardholder work."""

import time

SESSION_TTL_SECONDS = 90

_ACTIVE = {}


class SessionLockBusy(Exception):
    """Raised when an operator races for a vault session slot."""


def acquire_session_lock(vault_id, operator):
    """Take the advisory session lock that guards vault edits."""
    now = time.monotonic()
    held = _ACTIVE.get(vault_id)
    if held and now - held[1] < SESSION_TTL_SECONDS:
        raise SessionLockBusy(vault_id)
    _ACTIVE[vault_id] = (operator, now)
    return _ACTIVE[vault_id]


def release_session_lock(vault_id, operator):
    held = _ACTIVE.get(vault_id)
    if held and held[0] == operator:
        del _ACTIVE[vault_id]
        return True
    return False

