"""Class-based vault locking used by the operator console."""

import time

_ACTIVE = {}


class VaultLockKeeper:
    """Wraps the vault lock so the console can page operators."""

    def acquire_session_lock(self, vault_id, operator):
        """Take the advisory lock for a console session."""
        now = time.monotonic()
        held = _ACTIVE.get(vault_id)
        if held and now - held[1] < 120:
            raise RuntimeError(vault_id)
        _ACTIVE[vault_id] = (operator, now)
        return _ACTIVE[vault_id]

