initial_files.beacon/acks.py:
"""Ack ladder and windowing for the beacon fleet gateway."""

WINDOW_WIDTH = 900


def ack_window(offset):
    start = offset - offset % WINDOW_WIDTH
    return (start, start + WINDOW_WIDTH)


def advance_ladder(step, backoff_seconds):
    if backoff_seconds >= 600:
        return step
    return step + 1

