"""Per-account posted payment totals as CSV on stdout."""
import csv
import glob
import json
import os
import sys


def main():
    totals = {}
    for path in glob.glob(os.path.join(os.getcwd(), "**", "payments-*.json"),
                          recursive=True):
        with open(path, encoding="utf-8") as handle:
            for payment in json.load(handle)["payments"]:
                if payment["status"] == "posted":
                    account = payment["account"]
                    totals[account] = totals.get(account, 0) + payment["amount_cents"]
    out = csv.writer(sys.stdout, lineterminator="\n")
    out.writerow(["account", "total_cents"])
    for account in sorted(totals):
        out.writerow([account, totals[account]])


if __name__ == "__main__":
    main()

