"""Top five peak readings from the sensor dumps, as CSV on stdout."""
import csv
import glob
import os
import sys


def main():
    rows = []
    for path in glob.glob(os.path.join(os.getcwd(), "**", "readings-*.tsv"),
                          recursive=True):
        with open(path, newline="", encoding="utf-8") as handle:
            for row in csv.DictReader(handle, delimiter="\t"):
                if row["flag"] != "bad":
                    rows.append((row["sensor_id"], row["site"], row["reading"]))
    rows.sort(key=lambda row: (-float(row[2]), row[0]))
    out = csv.writer(sys.stdout, lineterminator="\n")
    out.writerow(["sensor_id", "site", "reading"])
    for row in rows[:5]:
        out.writerow(row)


if __name__ == "__main__":
    main()

