"""Merge wave exports into one row per order, as CSV on stdout."""
import csv
import glob
import os
import sys


def main():
    merged = {}
    paths = glob.glob(os.path.join(os.getcwd(), "**", "wave-*.csv"), recursive=True)
    for path in sorted(paths, key=os.path.basename):
        with open(path, newline="", encoding="utf-8") as handle:
            for row in csv.DictReader(handle):
                merged[row["order_id"]] = row
    out = csv.writer(sys.stdout, lineterminator="\n")
    out.writerow(["order_id", "carrier_service", "units", "priority"])
    for order_id in sorted(merged):
        row = merged[order_id]
        out.writerow([row["order_id"], row["carrier_service"], row["units"],
                      row["priority"]])


if __name__ == "__main__":
    main()

"""Replenishment alerts: rows below their reorder point, as CSV on stdout."""
import csv
import glob
import os
import sys


def main():
    alerts = []
    for path in glob.glob(os.path.join(os.getcwd(), "**", "stock-*.csv"),
                          recursive=True):
        with open(path, newline="", encoding="utf-8") as handle:
            for row in csv.DictReader(handle):
                if int(row["qty"]) < int(row["reorder_point"]):
                    alerts.append((row["sku"], row["bin"], row["qty"]))
    alerts.sort(key=lambda row: (int(row[2]), row[0]))
    out = csv.writer(sys.stdout, lineterminator="\n")
    out.writerow(["sku", "bin", "qty"])
    for row in alerts:
        out.writerow(row)


if __name__ == "__main__":
    main()

"""Label data: orders joined to customer names, as CSV on stdout."""
import csv
import glob
import os
import sys


def find(pattern):
    return sorted(glob.glob(os.path.join(os.getcwd(), "**", pattern),
                            recursive=True))


def main():
    names = {}
    for path in find("customers.csv"):
        with open(path, newline="", encoding="utf-8") as handle:
            for row in csv.DictReader(handle):
                names[row["code"]] = row["name"]
    rows = []
    for path in find("orders-*.csv"):
        with open(path, newline="", encoding="utf-8") as handle:
            for row in csv.DictReader(handle):
                name = names.get(row["customer_code"])
                if name is not None:
                    rows.append((row["order_id"], name))
    rows.sort(key=lambda row: (row[1], row[0]))
    out = csv.writer(sys.stdout, lineterminator="\n")
    out.writerow(["order_id", "customer_name"])
    for row in rows:
        out.writerow(row)


if __name__ == "__main__":
    main()

