"""Monthly settlement totals for the EU entity.

Launched from the project root, this sweeps the whole project tree
for acquirer batch extracts (transactions-*.csv, at any depth) and
prints the settlement totals defined by settlement_spec.md.
"""
import csv
from pathlib import Path


def main():
    totals = {}
    for path in sorted(Path.cwd().rglob("transactions-*.csv")):
        with open(path, newline="", encoding="utf-8") as fh:
            for row in csv.DictReader(fh):
                if row["status"] != "settled" or row["channel"] == "internal":
                    continue
                amount = int(row["amount_cents"])
                if row["type"] == "refund":
                    amount = -amount
                totals[row["merchant_id"]] = totals.get(row["merchant_id"], 0) + amount
    for merchant in sorted(totals):
        print("%s,%d" % (merchant, totals[merchant]))
    print("total,%d" % sum(totals.values()))


if __name__ == "__main__":
