"""Monthly settlement totals for the EU entity.

Sweeps every settlement extract under the launch directory and prints
the totals the finance spec defines.
"""
import csv
import json
from pathlib import Path

RULES = Path(__file__).resolve().parent / "settlement_rules.json"


def main():
    rules = json.loads(RULES.read_text(encoding="utf-8"))
    totals = {}
    for source in sorted(Path.cwd().rglob("transactions-*.csv")):
        with open(source, newline="", encoding="utf-8") as fh:
            for row in csv.DictReader(fh):
                if row["status"] != rules["count_status"]:
                    continue
                if row["channel"] == rules["exclude_channel"]:
                    continue
                amount = int(row["amount_cents"])
                if row["type"] == rules["subtract_type"]:
                    amount = -amount
                totals[row["merchant_id"]] = totals.get(row["merchant_id"], 0) + amount
    for merchant in sorted(totals):
        print("%s,%d" % (merchant, totals[merchant]))
    print("%s,%d" % (rules["total_label"], sum(totals.values())))


if __name__ == "__main__":
    main()

